--
-- Name: prc_calculo_interes_diario(date); Type: PROCEDURE; Schema: ca_cartera; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_cartera.prc_calculo_interes_diario(IN pid_fecha_ejecucion date)
    LANGUAGE plpgsql
    AS $$

declare  
-- variable declaration daniel
	dato record;
	dato_contable record;
	dato_entidad record;
	vrn_base_calculo	  int := 360;
    vrn_numero_credito    varchar(50);
	vrn_primera_cuota_pen int := 0;
	vrd_fecha_ultimo_pago TIMESTAMP ;
	vrd_fecha_mora	      TIMESTAMP;
    vrd_fecha_interes     TIMESTAMP;
	vrn_numero_dias		  int := 0;
	vrn_numero_dias_mora  int := 0;
	vrn_valor_interes	  numeric (12,4) ;
	vrn_valor			  numeric (12,4) ;
	vrn_tasa_mora   	  numeric (12,4) := 0.05;
	vrn_interes_mora	  numeric (12,4) ;
	vrn_tasa_interes	  numeric (12,4)  := 15;
	vrn_valor_interes_ta  numeric (12,4) ;
	vrn_valor_interes_ci  numeric (12,4) ;
	vrn_numero_dias_ci    INT:=0;
	vrn_tot_interes_ta    numeric (12,4) ;
    vrv_genero_mora       VARCHAR  (1) := 'N';   
    vrn_total_dia_interes numeric (12,4) ;
    vrn_tot_interes_mora numeric (12,4) ;
    vrn_total_dia_mora numeric (12,4) ;
    vrn_numero_ope_ant numeric  (12,4) := 0;
    vrn_valor_capital numeric (12,4):=0;
    vrv_bandera VARCHAR  (1);
    vrd_fecha_calculo_mora TIMESTAMP;
    vrd_fecha_calculo_interes TIMESTAMP;
    vrn_var numeric  (12,4);
    vrd_fech TIMESTAMP;
    vrd_fech_1 TIMESTAMP;
    vrd_fech_2 TIMESTAMP;
    vrn_cuota numeric;
    vrn_num_cuota numeric;
	
    
    fecha_inicio date;
    fecha_fin	  date;
    dia_ejecucion numeric(5) := date_part('day',pid_fecha_ejecucion);
 	dia_inicial   numeric (5) := extract (day from (select date_trunc('month',pid_fecha_ejecucion)));
 	mes_ejecucion numeric (5) := date_part('month',pid_fecha_ejecucion);
 	dia_fin_mes   numeric (5) := extract (day from (select date_trunc('month',pid_fecha_ejecucion) +'1month' ::interval -'1sec' ::interval));	

 	dia_inicio    VARCHAR(5) := extract (day from (select date_trunc('month',pid_fecha_ejecucion)));
 	mes	          VARCHAR(5) := date_part('month',pid_fecha_ejecucion);
 	dia_fin       VARCHAR(5) := extract (day from (select date_trunc('month',pid_fecha_ejecucion) +'1month' ::interval -'1sec' ::interval));	

    cnn_codigo_tipo_transaccion numeric(4);
    vrn_valor_contable numeric (12,4);
    cnv_observaciones_contable varchar(150);
     
	begin
		
		if dia_inicial < 10 then
	  	   dia_inicio := '0'||dia_inicio;
	    end if;
	
        if mes_ejecucion < 10 then
           mes := '0'||mes;
        end if;
   
        fecha_inicio := TO_DATE(date_part('year',pid_fecha_ejecucion)||mes|| dia_inicio ,'YYYYMMDD');
        fecha_fin    := TO_DATE(date_part('year',pid_fecha_ejecucion)||mes|| dia_fin ,'YYYYMMDD');
   
 		raise  notice  'fecha_inicio:(%)',  fecha_inicio;
 	    raise  notice  'fecha_fin:(%)',  fecha_fin;
        
		 for  dato in 
		     select  oc.codigo_entidad , 
		     	   codigo_operacion_crediticia , 
				   t.numero_cuota numero_cuota, 
				   fecha_inicio_pago fecha_inial, 
				   fecha_fin_pago fecha_fin, 
				   valor_saldo saldo,  
				   valor_capital capital, 
				   dias_interes_calculo, 
				   valor_interes interes_tabla, 
				   dias_mora_calculo, 
				   valor_mora mora, 
				   valor_rubro, 
				   valor_seguro, 
				   valor_pago, 
				   estado_cuota, 
				   oc.fecha_usuario_registra  fecha_liquida, 
				   fecha_calculo_mora fecha_mora_cal,
				  -- current_date fecha_interes,
				   oc.codigo_usuario_registra,
		           t.fecha_calculo_interes  fecha_registra_interes, 
		           coalesce (t.valor_interes_diario ,0) valor_interes_diario, 
		           t.valor_saldo_original saldo_tabla_original, 
		           t.numero_cuota cuota
		       from  ca_cartera.tabla_amortizacion t, 
		        	 ca_cartera.operacion_crediticia oc 
		       where t.codigo_operacion_crediticia  = oc.codigo 
		         and  t.estado_cuota  = 'P'
		         and  (pid_fecha_ejecucion between   t.fecha_inicio_pago  and  t.fecha_fin_pago  
		          or   t.fecha_fin_pago  <= pid_fecha_ejecucion)
		          order  by  fecha_inial
		  
		 			 
    loop 
    
    if  vrn_numero_ope_ant != dato.codigo_operacion_crediticia then  
       vrn_primera_cuota_pen :=0;
    end  if ;
    vrn_primera_cuota_pen := vrn_primera_cuota_pen + 1; 
    vrn_tot_interes_ta :=0;
	vrn_total_dia_interes := 0;
    vrn_tot_interes_mora:=0;
    vrn_total_dia_mora := 0;
    vrn_valor_interes := 0;
    vrn_interes_mora :=0;
    vrn_numero_dias_mora := 0;
    vrn_numero_dias := 0;
    vrv_genero_mora := 'N';
    vrn_num_cuota = dato.cuota;
    vrd_fech_2 := dato.fecha_registra_interes;
    vrn_cuota := vrn_primera_cuota_pen;
    vrv_bandera := null;
   
    
	/*Obtener tasa de interes vigente*/
   
	begin 
		 select pt.valor_tasa
		 into vrn_tasa_interes
		 from  ca_cartera.producto_tasa pt, 
		       ca_transaccional.producto p 
		 where pt.codigo_producto  = p.codigo 
		   and p.codigo_entidad = dato.codigo_entidad
		   and pt.estado = 'A'; 
		   
		   exception 
		   
		   when others then
		      raise exception 'existe mas de un valor para tasa_interes';			
		      rollback; 
		
	end;
     
       if  vrn_tasa_interes is null   then 
		    return ;
		 end if ;
      
      if  dato.fecha_registra_interes is   null  and  vrn_primera_cuota_pen = 1 then     
           dato.fecha_registra_interes := dato.fecha_liquida;
      end  if  ;
      
	  vrd_fech_1 := dato.fecha_registra_interes;
      
      if  (pid_fecha_ejecucion between  dato.fecha_inial and  dato.fecha_fin) or 
		  (vrn_primera_cuota_pen = 1 and  pid_fecha_ejecucion < dato.fecha_inial) then
		 /*Obtiene fecha de ultimo pago de cuota*/
		 if  not(pid_fecha_ejecucion between dato.fecha_inial and dato.fecha_fin ) and 
		  	(extract (day  from  pid_fecha_ejecucion) - extract (day  from (coalesce (dato.fecha_registra_interes,dato.fecha_inial))) <= 0) then
		  	/*Remplazar con consulta*/
		 	vrd_fecha_ultimo_pago := CURRENT_DATE; 
            
		  	vrn_numero_dias :=  extract (day  from  pid_fecha_ejecucion) -  extract (day  from  vrd_fecha_ultimo_pago);
		  else 
     	  	--vrn_numero_dias := (EXTRACT(DAY FROM vrd_fecha_calculo) -  EXTRACT(DAY FROM (COALESCE(dato.fecha_registra_interes,dato.fecha_inial)))/365.25);
            vrd_fech := dato.fecha_registra_interes;
            vrn_numero_dias := extract(days from (pid_fecha_ejecucion - coalesce  (dato.fecha_registra_interes,dato.fecha_inial)));
            if  vrn_numero_dias = 0 then  
               vrn_numero_dias = 1;
            end  if  ;
            vrv_bandera = 'I';
            vrd_fecha_calculo_interes = pid_fecha_ejecucion;
		  end if;
		  -- Calculo de interes diario	
          vrn_valor_capital := dato.saldo_tabla_original;
		  vrn_valor_interes := dato.saldo_tabla_original * ((vrn_tasa_interes / 100 ) / vrn_base_calculo * vrn_numero_dias);
		  -- Almacenar datos de calculo de interes diario si existe valor
		  vrn_tot_interes_ta := dato.valor_interes_diario+vrn_valor_interes;
		  vrn_total_dia_interes := dato.dias_interes_calculo + vrn_numero_dias;

	
	  end if; 
	   -- Calculo de interes en mora
	  if  pid_fecha_ejecucion > dato.fecha_fin then 
	  	--Obtenere tasa de mora incluido porcentaje que se agrega al interes normal
		vrn_tasa_mora := vrn_tasa_mora + vrn_tasa_interes;
		-- Agrega fecha de calculo de mora
		if dato.fecha_mora_cal is null then 
			vrd_fecha_mora := dato.fecha_fin;
		else
			vrd_fecha_mora :=  dato.fecha_mora_cal;
		end if;
        
        
		 -- Calculo de valor de mora
		 vrn_numero_dias_mora := extract(days from (pid_fecha_ejecucion - vrd_fecha_mora)) ;
         --vrn_interes_mora := dato.saldo_tabla_original * ((vrn_tasa_mora / 100)/360 * (vrn_numero_dias_mora));
         vrn_interes_mora := ((dato.saldo_tabla_original * 2) / 1000 * vrn_numero_dias_mora);        
         vrv_genero_mora = 'S';
         vrv_bandera = 'M';
         vrd_fecha_calculo_mora = pid_fecha_ejecucion;
		 -- Prueba
		 vrn_tot_interes_mora =dato.mora+vrn_interes_mora;
		 vrn_total_dia_mora = dato.dias_mora_calculo + vrn_numero_dias_mora;
				
	  end if;
	    
		-- Almacenar datos de calculo de interes por mora diaria si existe valor
												 codigo_entidad, 
												 codigo_agencia, 
												 codigo_operacion_crediticia, 
												 numero_cuota, 
												 fecha_calculo_interes, 
												 tasa_interes, 
												 valor_interes_diario, 
												 valor_mora_diario , 
												 numero_dias_interes, 	
												 fecha_calculo_mora, 
												 numero_dias_mora, 
												 codigo_usuario_registra, 
												 tipo_calculo)  
                                                 
						values  				(nextval('ca_cartera.sqc_calculo_interes'),
												 dato.codigo_entidad, 
												 1,--codigo_agencia 
												 dato.codigo_operacion_crediticia, 
												 dato.numero_cuota, 
												 vrd_fecha_calculo_interes,--fecha_calculo_interes 
												 vrn_tasa_interes,--tasa_interes 
												 COALESCE (vrn_valor_interes,0),--dato.valor_interes,--valor_interes 
                                                 COALESCE (vrn_interes_mora,0),--valor_mora 
                                                 COALESCE (vrn_numero_dias,0),--numero_dias interes
												 vrd_fecha_calculo_mora, --fecha calculo mora
												 COALESCE (vrn_numero_dias_mora,0),--dato.dias_mora_calculo,--dias_mora 
												 dato.codigo_usuario_registra,
												 vrv_bandera);
  --Generacion de proceso contable PROVISION CARTERA DIARIO
												
	if vrv_bandera = 'M' then 
	   cnn_codigo_tipo_transaccion := 11;
	   vrn_valor_contable := COALESCE (vrn_interes_mora,0);--valor_mora
	   cnv_observaciones_contable := 'Provision mora diaria';
    elsif vrv_bandera = 'I' then
       cnn_codigo_tipo_transaccion := 10;
	   vrn_valor_contable := COALESCE (vrn_valor_interes,0);--valor_interes
	   cnv_observaciones_contable := 'Provision interes diario';
    end if;
	
	 for  dato_contable in select    pc.codigo codigo_plan_cuenta ,
									 tp.codigo  codigo_transaccion_producto_con,
									 tp.descripcion transaccion,
									 pc.codigo_cuenta, 
									 pc.descripcion descripcion_cuenta ,
									 dp.debito_credito debito_credito,
									 cp.descripcion nombre_proceso, 
									 dp.orden orden, 
									 dp.valor_texto, 
									 pc.periodo_contable periodo_contable
								from ca_contables.transaccion_producto_pro_con tp,
									 ca_contables.cabecera_proceso_contable cp,
									 ca_contables.detalle_proceso_contable dp,
									 ca_contables.plan_cuenta pc 
							  where  tp.codigo_proceso_contable = cp.codigo 
								and  cp.codigo = dp.codigo_cabecera_proceso_con 
								and  pc.codigo = dp.codigo_plan_cuenta 
								and  tp.codigo_transaccion_producto = cnn_codigo_tipo_transaccion
							order by dp.orden loop 

			           
    call ca_contables.prc_inserta_registro_contable(
													dato_contable.codigo_plan_cuenta,
													dato_contable.codigo_transaccion_producto_con,
													dato.codigo_entidad, 
													1,
													dato_contable.debito_credito, 
													vrn_valor_contable, 
													'N', 
													cnv_observaciones_contable,
													2023, 
													'A', 
													pid_fecha_ejecucion, 
													1 );
	end loop;
 

  
   
   if  vrv_genero_mora = 'N' then  
   
	 begin 	
		update ca_cartera.tabla_amortizacion 
		  set valor_interes_diario=vrn_tot_interes_ta,
			  fecha_calculo_interes=pid_fecha_ejecucion,
			  dias_interes_calculo=vrn_total_dia_interes
		where codigo_operacion_crediticia  = dato.codigo_operacion_crediticia
         and  numero_cuota = dato.numero_cuota   
		 and  estado_cuota  = 'P';						
	   exception  
	   when others   then
	     raise exception 'Error al actualizar la operacion:(%)', dato.codigo_operacion_crediticia;
	  end;
   else  
	   begin 	
		update ca_cartera.tabla_amortizacion 
		  set valor_mora=vrn_tot_interes_mora,
			  fecha_calculo_mora=pid_fecha_ejecucion,
			  dias_mora_calculo=vrn_total_dia_mora
		where codigo_operacion_crediticia  = dato.codigo_operacion_crediticia
         and  numero_cuota = dato.numero_cuota   
		 and  estado_cuota  = 'P';						
	   exception  
	   when others   then
	     raise exception 'Error al actualizar la operacion:(%)', dato.codigo_operacion_crediticia;
	  end;
	 
   end  if ;
	  vrn_numero_ope_ant = dato.codigo_operacion_crediticia;										 
   
    end loop;
   	  if dia_ejecucion = dia_fin_mes then
	  	 for dato_entidad in select round (sum ( ci.valor_interes_diario),2) valor_interes, 
										    	ci.codigo_entidad
											from ca_cartera.calculo_interes ci 
											where  ci.tipo_calculo  = 'I'
											and ci.fecha_calculo_interes  between  fecha_inicio and fecha_fin
											group by codigo_entidad  loop
		       
		       
				 
		     	 for  dato_contable in select    pc.codigo codigo_plan_cuenta ,
										    	 tp.codigo  codigo_transaccion_producto_con,
												 tp.descripcion transaccion,
												 pc.codigo_cuenta, 
												 pc.descripcion descripcion_cuenta ,
												 dp.debito_credito debito_credito,
												 cp.descripcion nombre_proceso, 
												 dp.orden orden, 
												 dp.valor_texto, 
												 pc.periodo_contable periodo_contable
										   from ca_contables.transaccion_producto_pro_con tp,
												ca_contables.cabecera_proceso_contable cp,
												ca_contables.detalle_proceso_contable dp,
												ca_contables.plan_cuenta pc 
										 where  tp.codigo_proceso_contable = cp.codigo 
										   and  cp.codigo = dp.codigo_cabecera_proceso_con 
										   and    pc.codigo = dp.codigo_plan_cuenta 
										   and  tp.codigo_transaccion_producto = 8
										   order by dp.orden loop 

			           
			     call ca_contables.prc_inserta_registro_contable(
																	dato_contable.codigo_plan_cuenta,
																	dato_contable.codigo_transaccion_producto_con,
																	dato_entidad.codigo_entidad, 
																	1,
																	dato_contable.debito_credito, 
																	dato_entidad.valor_interes, 
																	'N', 
																	'Acreditacion mensual de intereses colocaciones ',
																	2023, 
																	'A', 
																	pid_fecha_ejecucion, 
																	1 );
	  		end loop;
		  end loop;
	  end if;
	end ;
$$;


ALTER PROCEDURE ca_cartera.prc_calculo_interes_diario(IN pid_fecha_ejecucion date) OWNER TO usr_caja_ahorro;

--
-- Name: prc_pago_credito_diario(date); Type: PROCEDURE; Schema: ca_cartera; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_cartera.prc_pago_credito_diario(IN pid_fecha_ejecucion date)
    LANGUAGE plpgsql
    AS $$
	
declare  
-- variable declaration daniel
	dato_credito record;
    dato_contable record ;
	vrn_base_calculo	  int := 360;
    vrn_numero_credito    varchar(50);
	vrd_fecha_calculo     TIMESTAMP := '2023-03-27'; --aaaa-mm-dd
	vrn_primera_cuota_pen int := 0;
	vrd_fecha_ultimo_pago TIMESTAMP;
	vrn_pago_total        numeric(12,4):=0;
	vrn_saldo_disponible  numeric (12,4):=0;
	vrn_numero_cuenta     numeric (10);
    vrn_saldo_total       numeric (12,4):=0;
    vrn_valor_contable    numeric (12,4) :=0;
    cnn_codigo_transaccion_pro numeric (4,2):=9;


begin 
  
  for  dato_credito in 
     select  codigo_operacion_crediticia codigo_credito, 
     	   oc.codigo_entidad codigo_entidad,
           oc.codigo_socio codigo_socio,
		   t.numero_cuota numero_cuota, 
		   fecha_inicio_pago fecha_inial, 
		   fecha_fin_pago fecha_fin, 
		   coalesce (valor_saldo,0) valor_saldo,  
		   coalesce (valor_capital,0) valor_capital, 
		   dias_interes_calculo, 
		   valor_interes interes_tabla, 
		   dias_mora_calculo, 
		   coalesce(valor_mora,0) valor_mora, 
		   coalesce(valor_rubro,0) valor_rubros ,
		   coalesce(valor_seguro) valor_seguro, 
		   coalesce(valor_pago,0) valor_cuota , 
		   estado_cuota, 
		   oc.fecha_usuario_registra  fecha_liquida, 
		   fecha_calculo_mora fecha_mora_cal,
		   oc.codigo_usuario_registra,
           t.fecha_usuario_registra  fecha_registra_interes, 
           coalesce (t.valor_interes_diario ,0) valor_interes_diario
       from  ca_cartera.tabla_amortizacion t, 
        	 ca_cartera.operacion_crediticia oc 
       where  t.codigo_operacion_crediticia  = oc.codigo 
         and  t.estado_cuota  = 'P'
         and t.fecha_fin_pago  = pid_fecha_ejecucion
         order by t.fecha_fin_pago loop 
  
    vrn_primera_cuota_pen := vrn_primera_cuota_pen + 1; 
    --Suma de los valores que debera cancelar en la cuota 
    vrn_pago_total := (dato_credito.valor_cuota+
   					   dato_credito.valor_mora+
   					   dato_credito.valor_seguro+
   					   dato_credito.valor_rubros);
   	--Extraer el valor del saldo disponible en la cuenta del socio 
   					   
    begin  
   		select  c.saldo_disponible, 
    	   		c.numero_cuenta, 
    	   		c.saldo_total
    	into    vrn_saldo_disponible, 
    	   		vrn_numero_cuenta,
    	   		vrn_saldo_total
    	from    ca_transaccional.cuenta c 
    	where   c.codigo_ingreso_persona  = dato_credito.codigo_socio;
        exception when  others then     
    		raise  exception  '(%)', sqlerrm ;
    		rollback ;
    end ;
    
    --Validar que saldo permita debido de credito 
    
    if  vrn_saldo_disponible >= vrn_pago_total then 
        --Insertar movimiento 
    
        										  codigo_entidad, 
        										  codigo_agencia, 
        										  codigo_transaccion,
        										  codigo_canal,
        										  codigo_producto,
        										  numero_cuenta, 
        										  valor_efectivo,
        										  valor_cheque,
        										  valor_transaccion,
        										  valor_saldo,
        										  observacion,
        										  debito_credito,
        										  nombre_maquina,
        										  codigo_usuario_registra,
        										  fecha_usuario_registra,
        										  codigo_usuario_actualiza,
        										  fecha_usuario_actualiza 
        										  
        										  ) 
     	values 
	 			  (nextval('ca_transaccional.sqc_movimiento'),
	 			   1, --codigo_entidad
	 			   1, --codigo_agencia
	 			   3, --codigo_transaccion
	 			   1, --codigo_canal
	 			   1,--codigo_producto,
	 			   vrn_numero_cuenta,  --numero_cuenta
	 			   vrn_pago_total,
	 			   0.0000,
	 			   vrn_pago_total,
	 			   (vrn_saldo_total  - vrn_pago_total),
	 			   'Pago automatico credito ' ||' cuota # '||dato_credito.numero_cuota,
	 			   'D',
	 			   'Pag. Cre. Aut.',
	 			   1,
	 			   pid_fecha_ejecucion,
	 			   1, 
	 			   pid_fecha_ejecucion);
	 			  
	  
			    update ca_transaccional.cuenta  
			       set saldo_total = (saldo_total  - vrn_pago_total), 
			           saldo_disponible = (saldo_disponible  - vrn_pago_total)
			     where codigo_ingreso_persona  = dato_credito.codigo_socio
			       and codigo_entidad  = dato_credito.codigo_entidad;
	      
		        update ca_cartera.tabla_amortizacion
			       set estado_cuota = 'C'
			     where codigo_operacion_crediticia = dato_credito.codigo_credito
			       and numero_cuota = dato_credito.numero_cuota;
	      
	      
	    
	    ---llamado a procedimiento contable de pago de credito
	      for  dato_contable in select pc.codigo codigo_plan_cuenta ,
							    	 tp.codigo  codigo_transaccion_producto_con,
									 tp.descripcion transaccion,
									 pc.codigo_cuenta, 
									 pc.descripcion descripcion_cuenta ,
									 dp.debito_credito debito_credito,
									 cp.descripcion nombre_proceso, 
									 dp.orden orden, 
									 dp.valor_texto, 
									 pc.periodo_contable periodo_contable
						   from ca_contables.transaccion_producto_pro_con tp,
								ca_contables.cabecera_proceso_contable cp,
								ca_contables.detalle_proceso_contable dp,
								ca_contables.plan_cuenta pc 
						 where  tp.codigo_proceso_contable = cp.codigo 
						   and  cp.codigo = dp.codigo_cabecera_proceso_con 
						   and    pc.codigo = dp.codigo_plan_cuenta 
						   and  tp.codigo_transaccion_producto = cnn_codigo_transaccion_pro
						   order by dp.orden loop 
	
			 	case when dato_contable.orden = 1 then vrn_valor_contable := dato_credito.valor_cuota;
			      	   when dato_contable.orden = 2 then vrn_valor_contable := dato_credito.valor_capital;
			      	   when dato_contable.orden = 3 then vrn_valor_contable := dato_credito.interes_tabla;
			      	   when dato_contable.orden = 4 then vrn_valor_contable := dato_credito.valor_mora;
			      end case ;
			           
			     call ca_contables.prc_inserta_registro_contable(
																	dato_contable.codigo_plan_cuenta,
																	dato_contable.codigo_transaccion_producto_con,
																	dato_credito.codigo_entidad, 
																	1,
																	dato_contable.debito_credito, 
																	vrn_valor_contable, 
																	'N', 
																	'Pago automatico credito codigo '|| dato_credito.codigo_credito||' cuota '||dato_credito.numero_cuota,
																	dato_contable.periodo_contable, 
																	'A', 
																	pid_fecha_ejecucion, 
																	1 );
	  end loop;
	 			  
    end  if  ;
    									 
    end loop;
    commit;
	end ;$$;


ALTER PROCEDURE ca_cartera.prc_pago_credito_diario(IN pid_fecha_ejecucion date) OWNER TO usr_caja_ahorro;

--
-- Name: prc_ejecuta_balance(date, date, numeric, integer); Type: PROCEDURE; Schema: ca_contables; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_contables.prc_ejecuta_balance(IN pid_fecha_inicio date, IN pid_fecha_fin date, IN pin_codigo_entidad numeric, IN pin_nivel_cuenta integer)
    LANGUAGE plpgsql
    AS $$
	
DECLARE 
-- variable declaration daniel
	dato_cuentas_balance record;
    valores_cuentas_balance record;
	

BEGIN
  truncate table ca_contables.tmp_resultado_balance;
  FOR dato_cuentas_balance IN
     
  	select pc.descripcion ,
	   	   substring (rcm.codigo_cuenta_contable, 1,pin_nivel_cuenta) nivel_cuenta --aqui va un parametro de entrada, el segundo parametro del substring 
	from   ca_contables.registro_contable_mayorizado rcm, 
	 	   ca_contables.plan_cuenta pc 
	where substring (rcm.codigo_cuenta_contable, 1,pin_nivel_cuenta)= pc.codigo_cuenta --aqui va un parametro de entrada, el segundo parametro del substring
	and   rcm.fecha_usuario_registra  between (pid_fecha_inicio)and (pid_fecha_fin)
	group by nivel_cuenta, pc.descripcion
			 
  LOOP
  
    
        										  				 codigo_entidad, 
        										  				 nivel_cuenta,
        										  				 valor_debito, 
        										  				 valor_credito, 
        										  				 fecha_usuario_registra, 
        										  				 descripcion
        										  ) 
     	VALUES
	 			  (nextval('ca_contables.sqc_registro_contable_diario'),
	 			   pin_codigo_entidad, 
	 			   dato_cuentas_balance.nivel_cuenta, 
	 			   0, 
	 			   0, 
	 			   ('2022-12-19'), 
	 			   'Paso I'
	 			   );
	 			  
    									 
      RAISE NOTICE 'Error';
    end loop;
   
    --Actualiza valores balance--
    FOR valores_cuentas_balance IN
     
  	select pc.descripcion ,
	   	   substring (rcm.codigo_cuenta_contable, 1,pin_nivel_cuenta) nivel_cuenta,  --aqui va un parametro de entrada, el segundo parametro del substring
	   	   rcm.debito_credito deb_cre, 
	   	   sum (rcm.saldo_fecha) saldo
	from   ca_contables.registro_contable_mayorizado rcm, 
	 	   ca_contables.plan_cuenta pc 
	where substring (rcm.codigo_cuenta_contable, 1,pin_nivel_cuenta)= pc.codigo_cuenta --aqui va un parametro de entrada, el segundo parametro del substring
	and   rcm.fecha_usuario_registra  between (pid_fecha_inicio)and (pid_fecha_fin)
	group by nivel_cuenta,  deb_cre, pc.descripcion
			 
  LOOP
  
       if valores_cuentas_balance.deb_cre = 'C' then 
        
           update ca_contables.tmp_resultado_balance 
	       set   valor_credito  = valor_credito + valores_cuentas_balance.saldo, 
	       		 descripcion = 'Paso II'
	       where nivel_cuenta = valores_cuentas_balance.nivel_cuenta ;	
	    
	   elsif  valores_cuentas_balance.deb_cre = 'D' then 
	       update ca_contables.tmp_resultado_balance 
	       set    valor_debito  = valor_debito + valores_cuentas_balance.saldo, 
	       descripcion = 'Paso II'
	       where  nivel_cuenta = valores_cuentas_balance.nivel_cuenta ;	
       end if ;
    	
       update ca_contables.tmp_resultado_balance 
	   set    saldo  = valor_credito - valor_debito
	   where  nivel_cuenta = valores_cuentas_balance.nivel_cuenta ;	
	      
    	
      RAISE NOTICE 'Error';
    end loop;
    --Actualiza valores balance--
    commit;
	end ;$$;


ALTER PROCEDURE ca_contables.prc_ejecuta_balance(IN pid_fecha_inicio date, IN pid_fecha_fin date, IN pin_codigo_entidad numeric, IN pin_nivel_cuenta integer) OWNER TO usr_caja_ahorro;

--
-- Name: prc_inserta_registro_contable(numeric, numeric, numeric, numeric, character varying, numeric, character varying, character varying, numeric, character varying, date, numeric); Type: PROCEDURE; Schema: ca_contables; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_contables.prc_inserta_registro_contable(IN pin_codigo_plan_cuenta numeric, IN pin_codigo_transaccion_producto numeric, IN pin_codigo_entidad numeric, IN pin_codigo_agencia numeric, IN piv_debito_credito character varying, IN pin_valor numeric, IN piv_mayorizado character varying, IN piv_numero_comprobante character varying, IN pin_periodo_contable numeric, IN piv_estado character varying, IN pid_fecha_usuario_registra date, IN pin_codigo_usuario_registra numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE 
-- variable declaration daniel
   
	begin
		
							   
					 										 codigo_plan_cuenta , 
					 										 codigo_transaccion_producto_pro_con , 
					 										 codigo_entidad , 
					 										 codigo_agencia , 
					 										 debito_credito , 
					 										 valor , 
					 										 mayorizado, 
					 										 numero_comprobante , 
					 										 periodo_contable , 
					 										 estado , 
					 										 fecha_usuario_registra , 
					 										 codigo_usuario_registra) 
			 													 
	values  (nextval('ca_contables.sqc_registro_contable_diario'),
			pin_codigo_plan_cuenta,
			pin_codigo_transaccion_producto, 
			pin_codigo_entidad,
			pin_codigo_agencia,
			piv_debito_credito,
			pin_valor,
			piv_mayorizado,
			piv_numero_comprobante,
			pin_periodo_contable,
			piv_estado,
			pid_fecha_usuario_registra,
			pin_codigo_usuario_registra);						
			   							   
	end ;
$$;


ALTER PROCEDURE ca_contables.prc_inserta_registro_contable(IN pin_codigo_plan_cuenta numeric, IN pin_codigo_transaccion_producto numeric, IN pin_codigo_entidad numeric, IN pin_codigo_agencia numeric, IN piv_debito_credito character varying, IN pin_valor numeric, IN piv_mayorizado character varying, IN piv_numero_comprobante character varying, IN pin_periodo_contable numeric, IN piv_estado character varying, IN pid_fecha_usuario_registra date, IN pin_codigo_usuario_registra numeric) OWNER TO usr_caja_ahorro;

--
-- Name: prc_registra_mayorizacion(date); Type: PROCEDURE; Schema: ca_contables; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_contables.prc_registra_mayorizacion(IN pid_fecha_ejecucion date)
    LANGUAGE plpgsql
    AS $$
	
DECLARE 
-- variable declaration daniel
	dato_registro_contable_diario record;
	

BEGIN
  
  FOR dato_registro_contable_diario IN
     
  select pc.codigo_cuenta codigo_cuenta_contable, 
			SUM (rcd.valor) valor_mayorizado, 
			rcd.debito_credito debito_credito,
			pc.codigo codigo_secuencia, 
			rcd.codigo_entidad  codigo_entidad
	from 	ca_contables.registro_contable_diario rcd, 
	 		ca_contables.plan_cuenta pc, 
	 		ca_contables.transaccion_producto_pro_con tppc 
	where 	pc.codigo = rcd.codigo_plan_cuenta 
	and   	rcd.codigo_transaccion_producto_pro_con  = tppc.codigo 
	and   	rcd.fecha_usuario_registra=(pid_fecha_ejecucion)
	and   	rcd.mayorizado  = 'N'
	group by pc.codigo , rcd.debito_credito, rcd.codigo_entidad 
			 
    LOOP
  
    
        										  				 codigo_cuenta_contable,
        										  				 codigo_cuenta_nivel_seis, 
        										  				 debito_credito, 
        										  				 saldo_fecha, 
        										  				 descripcion, 
        										  				 fecha_usuario_registra, 
        										  				 codigo_entidad, 
        										  				 codigo_usuario_registra
        										  ) 
     	VALUES
	 			  (nextval('ca_contables.sqc_registro_contable_diario'),
	 			   dato_registro_contable_diario.codigo_cuenta_contable, 
	 			   dato_registro_contable_diario.codigo_secuencia,
	 			   dato_registro_contable_diario.debito_credito, 
	 			   dato_registro_contable_diario.valor_mayorizado, 
	 			   'Registro mayorizado'||pid_fecha_ejecucion,
	 			   pid_fecha_ejecucion,
	 			   dato_registro_contable_diario.codigo_entidad, 
	 			   1);
	 			  
	 	
	 	begin 	
			update ca_contables.registro_contable_diario 
		  	set    mayorizado = 'S'
			where  fecha_usuario_registra  = pid_fecha_ejecucion;					
	   		exception  
	   		when OTHERS  then
	     		raise exception 'Error al actualizar la operacion:(%)', dato.codigo_operacion_crediticia;
	  end;
	 
	 
	 			  
    									 
      RAISE NOTICE 'Error';
    end loop;
    commit;
	end ;$$;


ALTER PROCEDURE ca_contables.prc_registra_mayorizacion(IN pid_fecha_ejecucion date) OWNER TO usr_caja_ahorro;

--
-- Name: prc_migra_cuenta_registro(); Type: PROCEDURE; Schema: ca_migraciones; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_migraciones.prc_migra_cuenta_registro()
    LANGUAGE plpgsql
    AS $$
DECLARE
 
  datos_cartera record;
  vrn_numero_credito varchar  (10);
  vrn_cod_producto numeric (10) := 12;
  vrn_codigo_entidad numeric (10) :=4;
  vrn_codigo_socio numeric (10);

begin
	
        
	
	            
	    for datos_cartera in    
								select p.numero_identificacion , 
									   cast (c.numero_cuenta as numeric) numero_cuenta, 
									   ip.codigo codigo_ingreso, 
									   tc2.plazo, 
									   tc2.monto_solicitado , 
									   tc2.fecha_liquidacion, 
									   oc.codigo 
								from   ca_personas.persona p, 
									   ca_personas.ingreso_persona ip, 
									   ca_transaccional.cuenta c, 
									   ca_migraciones.tmp_cedulas tc2 , 
									   ca_cartera.operacion_crediticia oc 
								where  p.numero_identificacion  = tc2.cedula_socio 
								and    p.codigo = ip.codigo_persona 
								and    c.codigo_ingreso_persona  = ip.codigo
								and    oc.codigo_socio  = ip.codigo 
								and    tc2.cedula_socio  not in ('0105419576','0104226022','0102304847') loop  
									
		       
		 
		  
		   
		      
		     
															codigo_operacion_cre , 
															codigo_cuenta_origen, 
															cuenta_destino, 
															codigo_usuario_registra,  
															fecha_usuario_registra )



				VALUES(nextval('ca_cartera.sqc_cuenta_acredita_ope_cre'), 
							   datos_cartera.codigo, 
							   datos_cartera.numero_cuenta,
							   '10000',
							  1,
							  '2023-06-09');
							
			
		  end loop;
end;$$;


ALTER PROCEDURE ca_migraciones.prc_migra_cuenta_registro() OWNER TO usr_caja_ahorro;

--
-- Name: prc_migra_ope_cre(); Type: PROCEDURE; Schema: ca_migraciones; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_migraciones.prc_migra_ope_cre()
    LANGUAGE plpgsql
    AS $$
DECLARE
 
  datos_cartera record;
  vrn_numero_credito varchar  (10);
  vrn_cod_producto numeric (10) := 3;
  vrn_codigo_entidad numeric (10) :=1;
  vrn_codigo_socio numeric (10);

begin
	
        
	
	            
	    for datos_cartera in    select p.numero_identificacion , 
									   c.numero_cuenta, 
									   ip.codigo codigo_ingreso, 
									   tc2.plazo, 
									   tc2.monto_solicitado , 
									   tc2.fecha_liquidacion 
								from   ca_personas.persona p, 
									   ca_personas.ingreso_persona ip, 
									   ca_transaccional.cuenta c, 
									   ca_migraciones.tmp_cedulas tc2 
								where  p.numero_identificacion  = tc2.cedula_socio 
								and    p.codigo = ip.codigo_persona 
								and    c.codigo_ingreso_persona  = ip.codigo
								and    p.codigo_entidad = 1
								and    tc2.cedula_socio  not in ('0105419576','0104226022','0102304847') loop  
									
		       
		    
			select pc.secuencia||  pc.ultimo
			  into vrn_numero_credito
			  from ca_cartera.parametro_cartera pc
			 where codigo_entidad  = vrn_codigo_entidad
			   and  codigo_producto = vrn_cod_producto;
		   
		  
		   
		      
		     
															codigo_entidad, 
															codigo_agencia, 
															codigo_socio, 
															codigo_producto, 
															codigo_tipo_periocidad, 
															codigo_estado_credito, 
															codigo_actividad_economica, 
															codigo_destino_credito, 
															codigo_tipo_acreditacion, 
															tipo_cuota, valor_tasa, 
															numero_cuota, 
															dias_gracia, 
															valor_solicitado, 
															observaciones, 
															fecha_usuario_registra, 
															codigo_usuario_registra,
															numero_credito)



				VALUES(nextval('ca_cartera.sqc_operacion_crediticia'), 
							       vrn_codigo_entidad, 
	    						   1,--datos_socio.codigo_agencia, 
	    						   datos_cartera.codigo_ingreso, --vrn_codigo_socio,
	    						   3,--datos_socio.codigo_producto, 
	    						   1,--datos_socio.codigo_tipo_periocidad, 
	    						   1,--datos_socio.codigo_estado_credito, 
	    						   1,--datos_socio.codigo_actividad_economica, 
	    						   1,--datos_socio.codigo_destino_credito, 
	    						   1,--datos_socio.codigo_tipo_acreditacion, 
	    						   'F',--datos_socio.tipo_cuota, 
	    						   13,--datos_socio.valor_tasa, 
	    						   datos_cartera.plazo,--datos_socio.numero_cuota, 
	    						   0,--datos_socio.dias_gracia, 
	    						   datos_cartera.monto_solicitado,--datos_socio.valor_solicitado, 
	    						   'Migracion Cartera',--datos_socio.observaciones, 
	    						   datos_cartera.fecha_liquidacion, --datos_socio.fecha_usuario_registra, 
	    						   1,--datos_socio.codigo_usuario_registra, 
	    						   vrn_numero_credito );
							
			update ca_cartera.parametro_cartera pc  
			  set  ultimo = ultimo+1
			  where pc.codigo_entidad  = vrn_codigo_entidad 
			  and   pc.codigo_producto  = vrn_cod_producto ;
								
		    
		  end loop;
end;$$;


ALTER PROCEDURE ca_migraciones.prc_migra_ope_cre() OWNER TO usr_caja_ahorro;

--
-- Name: prc_migra_tabla(numeric, numeric, numeric, numeric, date, character varying, numeric); Type: PROCEDURE; Schema: ca_migraciones; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_migraciones.prc_migra_tabla(IN pin_cantidad_solicitada numeric, IN pin_tasa_interes numeric, IN pin_periocidad numeric, IN pin_numero_cuota numeric, IN pid_fecha_ejecucion date, IN piv_tipo_calculo character varying, IN pin_periodo_gracia numeric)
    LANGUAGE plpgsql
    AS $$

declare  
-- variable declaration daniel
	dato_credito record;
    dato_contable record ;
	vrn_base_calculo	  numeric(10,2) := 360;
    vrn_numero_credito    varchar(50);
	vrd_fecha_calculo     TIMESTAMP := '2023-03-27'; --aaaa-mm-dd
	vrn_primera_cuota_pen numeric (10,2) := 0;
	vrd_fecha_ultimo_pago TIMESTAMP;
	vrn_pago_total        numeric(12,4):=0;
	vrn_saldo_disponible  numeric (12,4):=0;
	vrn_numero_cuenta     numeric (10);
    vrn_saldo_total       numeric (12,4):=0;
    vrn_valor_contable    numeric (12,4) :=0;
    cnn_codigo_transaccion_pro numeric (4,2):=9;
   
   
    vrd_fecha_inicio TIMESTAMP := pid_fecha_ejecucion;
	vrd_fecha_fin TIMESTAMP := pid_fecha_ejecucion;
    vrn_orden numeric (10,2):=1;
    vrn_numero_cuota numeric (10,2);
	vrn_result numeric (10,4);
	vrn_interes numeric (10,6) := ((pin_tasa_interes/100)/360);
	vrn_saldo numeric (10,6)   := pin_cantidad_solicitada;
	vrn_valor_interes numeric (10,6) ;
	vrn_pago numeric(10,6);
	vrn_capital numeric(10,6)    ;
    vrn_dias numeric(10);
    vrn_dias_ini numeric(10);
    vrn_dias_fin numeric(10);
    vrn_dias_tot varchar (100);
    var_uno numeric (10,6) ;
    var_dos numeric (10,6) ;
    var_tres numeric (10,6) ;


begin 
  
  delete from ca_migraciones.migracion_tabla;	
  if piv_tipo_calculo = 'V' then 
  while vrn_orden <= pin_numero_cuota loop 
	 vrn_numero_cuota := pin_numero_cuota; 
	 vrd_fecha_fin :=  vrd_fecha_inicio + interval '1 month';
	 vrn_capital := (pin_cantidad_solicitada / vrn_numero_cuota);
         if (vrn_orden = pin_numero_cuota) then 
                  vrn_capital := vrn_capital + (vrn_saldo - vrn_capital);
         end if;
     --vrn_dias = ChronoUnit.DAYS.between(vrd_fecha_inicio,vrd_fecha_fin);
     
      --*--
      vrn_dias_ini := extract (day from (select date_trunc('month',vrd_fecha_inicio)));
      vrn_dias_fin := extract (day from (select date_trunc('month',vrd_fecha_fin) +'1month' ::interval -'1sec' ::interval));
 	  vrn_dias := 30;-- (vrn_dias_fin -vrn_dias_ini);
 	 
 	  
     --*--
      vrn_valor_interes := vrn_saldo*(vrn_interes*(vrn_dias));
      vrn_pago := (vrn_capital + vrn_valor_interes);
     
      							   fecha_inicio, 
      							   fecha_fin, 
      							   saldo,
      							   capital, 
      							   interes, 
      							   pago, 
      							   dias)
      	     values                (vrn_orden, 
      	     						vrd_fecha_inicio,
      	     						vrd_fecha_fin,
      	     						vrn_saldo, 
      	     						vrn_capital, 
      	     						vrn_valor_interes, 
      	     						vrn_pago,
      	     						vrn_dias
      	    						); 
      vrn_saldo := vrn_saldo - vrn_capital;
      vrn_orden := vrn_orden + 1 ;
      vrd_fecha_inicio := vrd_fecha_fin;
	
  	
  end loop;
 
 else 
        while vrn_orden<= pin_numero_cuota loop                
                vrn_numero_cuota = pin_numero_cuota  - pin_periodo_gracia;
                vrn_result = ((vrn_interes*pin_periocidad) -vrn_numero_cuota);
                var_uno := vrn_result;
                vrn_result = (1-vrn_result)/(vrn_interes*pin_periocidad);
                var_dos := vrn_result;
                vrn_result = pin_cantidad_solicitada / vrn_result;
                var_tres := vrn_result;
                --BigDecimal bd = new BigDecimal(vrn_result).setScale(2, RoundingMode.HALF_UP);
                vrn_pago = vrn_result;--bd.doubleValue();
                vrd_fecha_fin =  vrd_fecha_inicio + interval '1 month';
                vrn_dias =30;-- ChronoUnit.DAYS.between(vrd_fecha_inicio,vrd_fecha_fin);
                vrn_valor_interes = vrn_saldo * (vrn_interes * vrn_dias);
                if (vrn_orden = pin_numero_cuota) then
                    vrn_pago =  vrn_result + ((vrn_saldo - (vrn_pago - vrn_valor_interes)));
                end if;
                vrn_capital = (vrn_pago - vrn_valor_interes);
                                
      							   fecha_inicio, 
      							   fecha_fin, 
      							   saldo,
      							   capital, 
      							   interes, 
      							   pago, 
      							   dias)
      	     values                (vrn_orden, 
      	     						vrd_fecha_inicio,
      	     						vrd_fecha_fin,
      	     						vrn_saldo, 
      	     						vrn_capital, 
      	     						vrn_valor_interes, 
      	     						vrn_pago,
      	     						vrn_dias
      	    						); 
                
                vrn_saldo = vrn_saldo - vrn_capital;
                vrn_orden = vrn_orden + 1 ;
                vrd_fecha_inicio = vrd_fecha_fin;
            end loop;
 end if ;


	end ;
	$$;


ALTER PROCEDURE ca_migraciones.prc_migra_tabla(IN pin_cantidad_solicitada numeric, IN pin_tasa_interes numeric, IN pin_periocidad numeric, IN pin_numero_cuota numeric, IN pid_fecha_ejecucion date, IN piv_tipo_calculo character varying, IN pin_periodo_gracia numeric) OWNER TO usr_caja_ahorro;

--
-- Name: prc_migra_tablas_amortizacion(); Type: PROCEDURE; Schema: ca_migraciones; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_migraciones.prc_migra_tablas_amortizacion()
    LANGUAGE plpgsql
    AS $$
DECLARE
 
  datos_tabla record;
  vrn_numero_credito varchar  (10);
  vrn_cod_producto numeric (10) := 3;
  vrn_codigo_entidad numeric (10) :=1;
  vrn_codigo_socio numeric (10);

begin
	
        
	
	            
	    for datos_tabla in    select mta.numero_cuota , 
									   mta.codigo_operacion, 
									   mta.fecha_inicio , 
									   mta.fecha_fin, 
									   mta.valor_saldo , 
									   mta.numero_cuota , 
									   mta.saldo_capital, 
									   mta.valor_capital, 
									   mta.interes , 
									   mta.valor_pago, 
									   mta.estado	   
								from   ca_migraciones.migra_tabla_amortizacion mta 
								order by numero_cuota loop  
																	
		       
		    
	   update ca_cartera.tabla_amortizacion 
	      set  fecha_inicio_pago = datos_tabla.fecha_inicio, 
	      	   fecha_fin_pago  = datos_tabla.fecha_fin,
	      	   valor_saldo  = datos_tabla.valor_saldo,
	      	   numero_cuota = datos_tabla.numero_cuota, 
	      	   valor_saldo_original = datos_tabla.saldo_capital, 
	      	   valor_capital = datos_tabla.valor_capital, 
	      	   valor_interes  = datos_tabla.interes, 
	      	   valor_pago  = datos_tabla.valor_pago,
	      	   estado_cuota = datos_tabla.estado
	  where   codigo_operacion_crediticia  = datos_tabla.codigo_operacion
	    and   numero_cuota  = datos_tabla.numero_cuota;
	      	   
	      	   
		    
		  end loop;
end;$$;


ALTER PROCEDURE ca_migraciones.prc_migra_tablas_amortizacion() OWNER TO usr_caja_ahorro;

--
-- Name: prc_prc_migra_garantia(); Type: PROCEDURE; Schema: ca_migraciones; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_migraciones.prc_prc_migra_garantia()
    LANGUAGE plpgsql
    AS $$
DECLARE
 
  datos_socio record;
  vrn_cod_producto numeric (10) := 3;
  vrn_codigo_entidad numeric (10) :=2;
  vrn_codigo_persona numeric (10);

begin
	
        
	
	            
	    for datos_socio in  SELECT codigo_entidad, 
	    						   codigo_agencia, 
	    						   codigo_operacion_crediticia, 
	    						   codigo_tipo_garantia,
	    						   estado, observacion, 
	    						   fecha_usuario_registra, 
	    						   codigo_usuario_registra, 
	    						   numero_identificacacion
							  FROM ca_migraciones.garantia_operacion_cre_migra loop  
									
		       
		    
		   
		
		     select  p2.codigo 
		       into  vrn_codigo_persona
		       from  ca_personas.persona p2 
			    where  p2.numero_identificacion  = datos_socio.numero_identificacacion;
		   
		   
		   
		      
		     
															codigo_entidad, 
															codigo_agencia, 
															codigo_operacion_crediticia, 
															codigo_persona_garante, 
															codigo_tipo_garantia, 
															estado, 
															observacion, 
															fecha_usuario_registra, 
															codigo_usuario_registra)




				VALUES(nextval('ca_cartera.sqc_garantia_operacion_cre'), 
							       datos_socio.codigo_entidad, 
	    						   datos_socio.codigo_agencia, 
	    						   datos_socio.codigo_operacion_crediticia, 
	    						   vrn_codigo_persona,
	    						   datos_socio.codigo_tipo_garantia,
	    						   datos_socio.estado, 
	    						   datos_socio.observacion, 
	    						   datos_socio.fecha_usuario_registra, 
	    						   datos_socio.codigo_usuario_registra  );
							
								
		    
		  end loop;
end;$$;


ALTER PROCEDURE ca_migraciones.prc_prc_migra_garantia() OWNER TO usr_caja_ahorro;

--
-- Name: prc_actualiza_nombre_persona(); Type: PROCEDURE; Schema: ca_personas; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_personas.prc_actualiza_nombre_persona()
    LANGUAGE plpgsql
    AS $$
DECLARE
 
  datos_persona record;
  cnn_codigo_entidad numeric (1) :=2;

begin
	
        
	
	            
	    for datos_persona in  select pn.nombres ||' '|| pn.primer_apellido ||' '|| pn.segundo_apellido nombres ,
	   								pn.codigo_persona codigo
								from ca_personas.persona_natural pn, 
									 ca_personas.persona p 
								where p.codigo  = pn.codigo_persona 
								and   p.codigo_entidad  = cnn_codigo_entidad  loop  
		              
		      
		     
		     update ca_personas.persona  set nombres = datos_persona.nombres 
		     where codigo = datos_persona.codigo;
								
		    
		  end loop;
end;$$;


ALTER PROCEDURE ca_personas.prc_actualiza_nombre_persona() OWNER TO usr_caja_ahorro;

--
-- Name: prc_genera_cuenta(); Type: PROCEDURE; Schema: ca_personas; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_personas.prc_genera_cuenta()
    LANGUAGE plpgsql
    AS $$
DECLARE
 
  datos_socio record;
  num_secuencia numeric (10);
  num_ultimo varchar  (10);
  vrn_cod_producto numeric (10) := 4;
  vrn_codigo_entidad numeric (10) :=2;

begin
	
        
	
	            
	    for datos_socio in  select ip.codigo
							from ca_personas.ingreso_persona ip 
							where ip.codigo_entidad = vrn_codigo_entidad
							
						    order by codigo asc loop  
									
		       
		    
			select 
				   pc.secuencia , 
				   pc.ultimo 
		    into   
		    	   num_secuencia, 
		    	   num_ultimo
			from   ca_transaccional.parametro_cuenta pc 
			where  pc.codigo_entidad = vrn_codigo_entidad
			and    pc.codigo_producto  = vrn_cod_producto;
		   
		   
		   
		   
		      
		     
												codigo_ingreso_persona, 
												codigo_entidad, 
												numero_cuenta, 
												codigo_producto, 
												saldo_total, 
												saldo_disponible, 
												saldo_restringido, 
												codigo_estado_cuenta, 
												codigo_usuario_registra, 
												fecha_usuario_registra)


				VALUES(nextval('ca_transaccional.sqc_cuenta'), 
							   datos_socio.codigo, 
							   vrn_codigo_entidad, 
							   (num_secuencia||num_ultimo),
							   vrn_cod_producto, 
							   0,
							   0,
							   0,
							   1,
							   1,
							   ('2023-09-09') );
							
			update ca_transaccional.parametro_cuenta pc  
			  set  ultimo = ultimo+1
			  where pc.codigo_entidad  = vrn_codigo_entidad 
			  and   pc.codigo_producto  = vrn_cod_producto ;
								
		    
		  end loop;
end;$$;


ALTER PROCEDURE ca_personas.prc_genera_cuenta() OWNER TO usr_caja_ahorro;

--
-- Name: prc_genera_socio(); Type: PROCEDURE; Schema: ca_personas; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_personas.prc_genera_socio()
    LANGUAGE plpgsql
    AS $$
DECLARE
 
  datos_persona record;
  num_secuencia numeric (10);
  num_ultimo numeric (10);
  cnn_codigo_entidad numeric (10) := 2;

begin
	
        
	
	            
	    for datos_persona in  select   codigo,
									   pm.codigo_tipo_persona , 
									   pm.codigo_entidad 
								from  ca_personas.persona pm 
								where pm.codigo_entidad  = cnn_codigo_entidad
								order by codigo asc loop  
									
		    select secuencia, ultimo 
		      into num_secuencia, num_ultimo
		    from ca_personas.parametro_persona pp  
		    where  codigo_entidad  = datos_persona.codigo_entidad;
		   
		   
		   
		   
		      
		     
													codigo_persona, 
													codigo_entidad, 
													codigo_agencia, 
													codigo_estado, 
													codigo_tipo_relacion, 
													fecha_usuario_registra, 
													fecha_usuario_actualiza, 
													codigo_usuario_registra, 
													codigo_usuario_actualiza, 
													numero_socio)

				VALUES(nextval('ca_personas.sqc_socio'), 
							   datos_persona.codigo, 
							   datos_persona.codigo_entidad, 
							   1,
							   1,
							   1,
							   ('17-04-2023'),
							   ('17-04-2023'),
							   1,
							   1,
							   num_secuencia+num_ultimo
							  
								);
							
			update ca_personas.parametro_persona pp 
			  set  ultimo = ultimo+1
			  where pp.codigo_entidad  = datos_persona.codigo_entidad;
								
		    
		  end loop;
end;$$;


ALTER PROCEDURE ca_personas.prc_genera_socio() OWNER TO usr_caja_ahorro;

