CREATE PROCEDURE ca_personas.prc_migra_persona()
    LANGUAGE plpgsql
    AS $$
DECLARE
 
  datos_persona record;

begin
	
        
	
	            
	    for datos_persona in  select pm.codigo_tipo_identificacion , 
									   pm.codigo_tipo_persona , 
									   pm.numero_identificacion , 
									   pm.nombres , 
									   pm.correo_electronico , 
