												 fecha_usuario_actualiza, 
												 codigo_usuario_registra, 
												 codigo_usuario_actualiza, 
												 codigo_entidad 
												 )
				VALUES(nextval('ca_personas.sqc_persona'), 
							   datos_persona.codigo_tipo_identificacion, 
							   datos_persona.codigo_tipo_persona, 
							   datos_persona.numero_identificacion, 
							   datos_persona.nombres, 
							   datos_persona.correo_electronico, 
							   datos_persona.fecha_caducidad_identificacion, 
							   datos_persona.fecha_usuario_registra,
							   datos_persona.fecha_usuario_actualiza, 
							   datos_persona.codigo_usuario_registra, 
							   datos_persona.codigo_usuario_actualiza, 
							   datos_persona.codigo_entidad
							  
								);
								
		    
		  end loop;
end;$$;


