												datos_persona_direccion_tra.referencia, 
												
												datos_persona_direccion_tra.fecha_usuario_registra, 
												datos_persona_direccion_tra.codigo_usuario_registra, 
												datos_persona_direccion_tra.codigo_usuario_actualiza, 
												datos_persona_direccion_tra.fecha_usuario_actualiza,
												datos_persona_direccion_tra.lugar_trabajo , 
