--
-- Name: fnt_calculo_interes_ahorro(); Type: FUNCTION; Schema: ca_procesos_automaticos; Owner: usr_caja_ahorro
--

CREATE FUNCTION ca_procesos_automaticos.fnt_calculo_interes_ahorro() RETURNS character
    LANGUAGE plpgsql
    AS $$
	declare 
	vrn_valor NUMERIC(1) := 0;
	vrv_ejecuto char := 'N';
	begin
		--Verifica si ya se ejecuto el proceso
		begin
			select count(1)
			into vrn_valor
			from ca_procesos_automaticos.proceso_automatico_control pac 
			where pac.codigo_proceso_automatico  = 1
			and   pac.fecha_ejecuta  = now();
		exception 
			when others then
				return vrv_ejecuto;
		end ;
	
	-- ingresa solo si no hay registro de para calcular interes
	if vrn_valor = 0 then
		-- Ejecuta procesos de calculos
		call ca_transaccional.prc_calculo_interes_ahorro('2023-08-30');
	
		-- registra ejecucion 
		begin
			VALUES(1, 1, now(), 'A', 1, now()); 
			vrv_ejecuto := 'S';
		exception		
			when others then
				return vrv_ejecuto;
		end;
	else
		return vrv_ejecuto;
	end if;
	return vrv_ejecuto;
end;

$$;


ALTER FUNCTION ca_procesos_automaticos.fnt_calculo_interes_ahorro() OWNER TO usr_caja_ahorro;

