--
-- Name: prc_calculo_interes_ahorro(date); Type: PROCEDURE; Schema: ca_transaccional; Owner: usr_caja_ahorro
--

CREATE PROCEDURE ca_transaccional.prc_calculo_interes_ahorro(IN pid_fecha_ejecucion date)
    LANGUAGE plpgsql
    AS $$
DECLARE
 calculo_interes NUMERIC(10,6) := 0;

datos_cuenta record;
dato_contable record;
dato_entidad record;

 dia_ejecucion NUMERIC(5) := date_part('day',pid_fecha_ejecucion);
 dia_inicial   NUMERIC(5) := extract (day from (select date_trunc('month',pid_fecha_ejecucion)));
 mes_ejecucion NUMERIC(5) := date_part('month',pid_fecha_ejecucion);
 dia_fin_mes   NUMERIC(5) := extract (day from (select date_trunc('month',pid_fecha_ejecucion) +'1month' ::interval -'1sec' ::interval));	

 dia_inicio    VARCHAR(5) := extract (day from (select date_trunc('month',pid_fecha_ejecucion)));
 mes	       VARCHAR(5) := date_part('month',pid_fecha_ejecucion);
 dia_fin       VARCHAR(5) := extract (day from (select date_trunc('month',pid_fecha_ejecucion) +'1month' ::interval -'1sec' ::interval));	

 fecha_inicio date;
 fecha_fin	  date;
 total_interes NUMERIC(10,2) := 0;
 vrn_valor_interes numeric (10,2) :=3.5;
 vrn_base_calculo numeric(10,2) := 360;
 vrn_calculo_interes numeric(10,2);
 vrn_total_interes_mensual numeric(10,2);

  vrn_saldo_disponible numeric(10,2);
  vrn_saldo_total numeric(10,2);
  vrv_numero_cuenta varchar(10);
  vrn_codigo_entidad numeric (10);
  vrn_codigo_producto numeric (10);

begin
	if dia_inicial < 10 then
	  dia_inicio := '0'||dia_inicio;
	end if;
	
    if mes_ejecucion < 10 then
      mes := '0'||mes;
    end if;
   
    fecha_inicio := TO_DATE(date_part('year',pid_fecha_ejecucion)||mes|| dia_inicio ,'YYYYMMDD');
    fecha_fin    := TO_DATE(date_part('year',pid_fecha_ejecucion)||mes|| dia_fin ,'YYYYMMDD');
        
	
	            
	    for datos_cuenta in  select c.saldo_total saldo_total, 
									c.codigo codigo, 
									c.codigo_producto codigo_producto , 
									p.codigo_actividad_financiera codigo_actividad_financiera, 
									c.numero_cuenta numero_cuenta , 
									c.codigo_entidad codigo_entidad 
		             from ca_transaccional.cuenta c,
		             	  ca_transaccional.producto p 
		            where c.codigo_producto  = p.codigo 
		              and p.codigo_actividad_financiera  = 1  
		               loop  
		              
		      vrn_calculo_interes :=  ROUND(((vrn_valor_interes/100) * datos_cuenta.saldo_total)/vrn_base_calculo,4);  
		     
																	 codigo_producto, 
																	 codigo_actividad_financiera, 
																	 codigo_entidad,
																	 saldo_total, 
																	 tasa_interes, 
																	 interes_calculado, 
																	 numero_cuenta,
																	 fecha_usuario_registra, 
																	 codigo_usuario_registra 
																	 )
				VALUES(nextval('ca_transaccional.sqc_provision_interes_diario'),
								datos_cuenta.codigo_producto, 
								datos_cuenta.codigo_actividad_financiera, 
								datos_cuenta.codigo_entidad, 
								datos_cuenta.saldo_total, 
								vrn_valor_interes, 
								vrn_calculo_interes,
								datos_cuenta.numero_cuenta, 
								pid_fecha_ejecucion, 
								1);
								
		     --Registro Contable Diario por provision de interes
			
		     	  for  dato_contable in select   pc.codigo codigo_plan_cuenta ,
										    	 tp.codigo  codigo_transaccion_producto_con,
												 tp.descripcion transaccion,
												 pc.codigo_cuenta, 
												 pc.descripcion descripcion_cuenta ,
												 dp.debito_credito debito_credito,
												 cp.descripcion nombre_proceso, 
												 dp.orden orden, 
												 dp.valor_texto, 
												 pc.periodo_contable periodo_contable
										   from ca_contables.transaccion_producto_pro_con tp,
												ca_contables.cabecera_proceso_contable cp,
												ca_contables.detalle_proceso_contable dp,
												ca_contables.plan_cuenta pc 
										 where  tp.codigo_proceso_contable = cp.codigo 
										   and  cp.codigo = dp.codigo_cabecera_proceso_con 
										   and    pc.codigo = dp.codigo_plan_cuenta 
										   and  tp.codigo_transaccion_producto = 6
										   order by dp.orden loop 

			           
			     call ca_contables.prc_inserta_registro_contable(
																	dato_contable.codigo_plan_cuenta,
																	dato_contable.codigo_transaccion_producto_con,
																	datos_cuenta.codigo_entidad, 
																	1,
																	dato_contable.debito_credito, 
																	vrn_calculo_interes, 
																	'N', 
																	'Provision diaria de intereses captaciones',
																	2023, 
																	'A', 
																	pid_fecha_ejecucion, 
																	1 );
	  		end loop;
	  	--Fin registro de provision de interes de ahorro 
			
							
			
			if dia_ejecucion = 31 then --dia_fin_mes then
		         -- ACREDITO INTERES EN LA CUENTA DE AHORROS 
				 select sum(cpi.interes_calculado)
				   into total_interes
				   from ca_transaccional.provision_interes_diario cpi 
				  where cpi.fecha_usuario_registra  between fecha_inicio and fecha_fin
				    and cpi.numero_cuenta  = datos_cuenta.numero_cuenta
				    and cpi.codigo_producto  =  datos_cuenta.codigo_producto; 
				   
				   
															codigo_entidad, 
															codigo_agencia, 
															codigo_transaccion,
															codigo_canal,
															codigo_producto, 
															numero_cuenta, 
															valor_efectivo,
															valor_cheque,
															valor_transaccion,
															valor_saldo,
															observacion,
															debito_credito,
															nombre_maquina,
															codigo_usuario_registra,
															fecha_usuario_registra,
															codigo_usuario_actualiza,
															fecha_usuario_actualiza)
				VALUES (nextval('ca_transaccional.sqc_movimiento'),
	 			   datos_cuenta.codigo_entidad,--codigo entidad
	 			   1,--codigo agencia 
	 			   5,--codigo transaccion
				   1,--codigo canal 
				   1, --codigo producto, 
				   datos_cuenta.numero_cuenta, 
	 			   total_interes,--valor efectivo
	 			   0.0000,--valor cheque
	 			   total_interes, --valor transaccion 
	 			   (datos_cuenta.saldo_total +total_interes),--valor_saldo,
	 			   'ACREDITACION INTERES MENSUAL',--observacion
	 			   'C',--debito-creito
	 			   'ACRE_INTE_MENSUAL --nombre maquina',
	 			   1,--codigo usuario registra
	 			   now(),--fecha_usuario_registra,
	 			   1, --codigo usuario actualiza 
	 			   now() -- fecha usuario actualiza
	 			   );
	 			  
	 			  vrn_saldo_disponible := (datos_cuenta.saldo_total +total_interes);
	 			  vrn_saldo_total := datos_cuenta.saldo_total +total_interes;
	 			  vrv_numero_cuenta := datos_cuenta.numero_cuenta;
	 			  
	 			  update ca_transaccional.cuenta  
	 			     set saldo_disponible = vrn_saldo_disponible ,
	 			     	 saldo_total  = vrn_saldo_total
	 			   where numero_cuenta = vrv_numero_cuenta;
	 			   

				  
			 end if; 
			
	    end loop; 
	    
	   if dia_ejecucion = 31 then --dia_fin_mes then
	   
	       for dato_entidad in select sum ( cpi.interes_calculado) valor_interes, 
		              		 				cpi.codigo_entidad, 
			     							cpi.codigo_producto 
			     				from ca_transaccional.provision_interes_diario cpi 
				 				where cpi.fecha_usuario_registra  between fecha_inicio and fecha_fin
		     	 				group by codigo_entidad, codigo_producto  loop
		       
		       
				 
		     	  for  dato_contable in select   pc.codigo codigo_plan_cuenta ,
										    	 tp.codigo  codigo_transaccion_producto_con,
												 tp.descripcion transaccion,
												 pc.codigo_cuenta, 
												 pc.descripcion descripcion_cuenta ,
												 dp.debito_credito debito_credito,
												 cp.descripcion nombre_proceso, 
												 dp.orden orden, 
												 dp.valor_texto, 
												 pc.periodo_contable periodo_contable
										   from ca_contables.transaccion_producto_pro_con tp,
												ca_contables.cabecera_proceso_contable cp,
												ca_contables.detalle_proceso_contable dp,
												ca_contables.plan_cuenta pc 
										 where  tp.codigo_proceso_contable = cp.codigo 
										   and  cp.codigo = dp.codigo_cabecera_proceso_con 
										   and    pc.codigo = dp.codigo_plan_cuenta 
										   and  tp.codigo_transaccion_producto = 5
										   order by dp.orden loop 

			           
			     call ca_contables.prc_inserta_registro_contable(
																	dato_contable.codigo_plan_cuenta,
																	dato_contable.codigo_transaccion_producto_con,
																	dato_entidad.codigo_entidad, 
																	1,
																	dato_contable.debito_credito, 
																	dato_entidad.valor_interes, 
																	'N', 
																	'Acreditacion mensual de intereses captaciones ',
																	2023, 
																	'A', 
																	pid_fecha_ejecucion, 
																	1 );
	  		end loop;
		  end loop;
	 end if ;

end;$$;


ALTER PROCEDURE ca_transaccional.prc_calculo_interes_ahorro(IN pid_fecha_ejecucion date) OWNER TO usr_caja_ahorro;

--
-- Name: generate_amortization_table(numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: usr_caja_ahorro
--

CREATE FUNCTION public.generate_amortization_table(monto_solicitado numeric, interes numeric, plazo_meses integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    payment_date DATE;
    payment_amount NUMERIC;
    principal_payment NUMERIC;
    interest_payment NUMERIC;
    remaining_balance NUMERIC := monto_solicitado;
BEGIN
    -- Eliminar registros anteriores de la tabla de amortización
    DELETE FROM tabla_migracion;

    -- Calcular la tasa de interés mensual
    DECLARE
        monthly_interest_rate NUMERIC := interes / 12;
    BEGIN
        FOR i IN 1..plazo_meses LOOP
            -- Calcular el pago de intereses y el pago de capital
            interest_payment := remaining_balance * monthly_interest_rate;
            principal_payment := payment_amount - interest_payment;

            -- Calcular el nuevo saldo restante
            remaining_balance := remaining_balance - principal_payment;

            -- Calcular la fecha del pago (puedes ajustar esto según tu lógica)
            payment_date := CURRENT_DATE + (i || ' months')::INTERVAL;

            -- Insertar el registro en la tabla de amortización
                 payment_date, payment_amount, principal_payment,
                 interest_payment, remaining_balance)
            VALUES
                (monto_solicitado, interes, plazo_meses,
                 payment_date, payment_amount, principal_payment,
                 interest_payment, remaining_balance);
        END LOOP;
    END;
END;
$$;


ALTER FUNCTION public.generate_amortization_table(monto_solicitado numeric, interes numeric, plazo_meses integer) OWNER TO usr_caja_ahorro;

